const scanTimesForStudentDay = `-- name: ScanTimesForStudentDay :many
SELECT scanned_at
FROM gate_scans
WHERE tenant_id = $1 AND student_id = $2 AND day = $3
ORDER BY scanned_at
`

type ScanTimesForStudentDayParams struct {
	TenantID  pgtype.UUID
	StudentID pgtype.UUID
	Day       pgtype.Date
}

func (q *Queries) ScanTimesForStudentDay(ctx context.Context, arg ScanTimesForStudentDayParams) ([]pgtype.Timestamptz, error) {
	rows, err := q.db.Query(ctx, scanTimesForStudentDay, arg.TenantID, arg.StudentID, arg.Day)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []pgtype.Timestamptz
	for rows.Next() {
		var scanned_at pgtype.Timestamptz
		if err := rows.Scan(&scanned_at); err != nil {
			return nil, err
		}
		items = append(items, scanned_at)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setSettings = `-- name: SetSettings :exec
INSERT INTO attendance_settings (tenant_id, register_due_time, edit_window_days, low_attendance_percent,
                                 morning_start, evening_start, late_after_minutes, updated_by)
VALUES ($1, $2::time, $3,
        $4, $5::time, $6::time,
        $7, $8)
ON CONFLICT (tenant_id) DO UPDATE
SET register_due_time = EXCLUDED.register_due_time, edit_window_days = EXCLUDED.edit_window_days,
    low_attendance_percent = EXCLUDED.low_attendance_percent, morning_start = EXCLUDED.morning_start,
    evening_start = EXCLUDED.evening_start, late_after_minutes = EXCLUDED.late_after_minutes,
    updated_at = now(), updated_by = EXCLUDED.updated_by
`

type SetSettingsParams struct {
	TenantID             pgtype.UUID
	RegisterDueTime      pgtype.Time
	EditWindowDays       int32
	LowAttendancePercent int32
	MorningStart         pgtype.Time
	EveningStart         pgtype.Time
	LateAfterMinutes     int32
	UpdatedBy            pgtype.UUID
}

// The row is created the first time the settings are saved; until then reads use the defaults.
func (q *Queries) SetSettings(ctx context.Context, arg SetSettingsParams) error {
	_, err := q.db.Exec(ctx, setSettings,
		arg.TenantID,
		arg.RegisterDueTime,
		arg.EditWindowDays,
		arg.LowAttendancePercent,
		arg.MorningStart,
		arg.EveningStart,
		arg.LateAfterMinutes,
		arg.UpdatedBy,
	)
	return err
}

const shareCard = `-- name: ShareCard :one
SELECT id, student_id, status, issued_at, disabled_at, disabled_reason
FROM student_cards
WHERE tenant_id = $1 AND id = $2
FOR SHARE
`

type ShareCardParams struct {
	TenantID pgtype.UUID
	ID       pgtype.UUID
}

type ShareCardRow struct {
	ID             pgtype.UUID
	StudentID      pgtype.UUID
	Status         string
	IssuedAt       pgtype.Timestamptz
	DisabledAt     pgtype.Timestamptz
	DisabledReason pgtype.Text
}

// FOR SHARE: a scan holds the card until it commits, so disabling it (FOR UPDATE) waits for scans in flight
// and every scan that commits before the disable returns was made while the card was still active.
func (q *Queries) ShareCard(ctx context.Context, arg ShareCardParams) (ShareCardRow, error) {
	row := q.db.QueryRow(ctx, shareCard, arg.TenantID, arg.ID)
	var i ShareCardRow
	err := row.Scan(
		&i.ID,
		&i.StudentID,
		&i.Status,
		&i.IssuedAt,
		&i.DisabledAt,
		&i.DisabledReason,
	)
	return i, err
}

const studentDays = `-- name: StudentDays :many
SELECT g.day, g.section_id, cur.status, cur.method,
       EXISTS (SELECT 1 FROM attendance_records c
                WHERE c.tenant_id = cur.tenant_id AND c.register_id = cur.register_id AND c.student_id = cur.student_id
                  AND c.method = 'correction') AS corrected
FROM (
    SELECT DISTINCT ON (r.register_id) r.tenant_id, r.register_id, r.student_id, r.status, r.method
    FROM attendance_records r
    JOIN attendance_registers g ON g.tenant_id = r.tenant_id AND g.id = r.register_id
    WHERE r.tenant_id = $1 AND r.student_id = $2 AND g.status = 'submitted'
      AND g.day BETWEEN $3::date AND $4::date
    ORDER BY r.register_id, r.version DESC
) cur
JOIN attendance_registers g ON g.tenant_id = cur.tenant_id AND g.id = cur.register_id
WHERE cur.status <> 'left'
ORDER BY g.day, g.section_id
`

type StudentDaysParams struct {
	TenantID  pgtype.UUID
	StudentID pgtype.UUID
	FromDay   pgtype.Date
	ToDay     pgtype.Date
}

type StudentDaysRow struct {
	Day       pgtype.Date
	SectionID pgtype.UUID
	Status    string
	Method    string
	Corrected bool
}

// One student's current status on each day of a range, from submitted registers.
func (q *Queries) StudentDays(ctx context.Context, arg StudentDaysParams) ([]StudentDaysRow, error) {
	rows, err := q.db.Query(ctx, studentDays,
		arg.TenantID,
		arg.StudentID,
		arg.FromDay,
		arg.ToDay,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StudentDaysRow
	for rows.Next() {
		var i StudentDaysRow
		if err := rows.Scan(
			&i.Day,
			&i.SectionID,
			&i.Status,
			&i.Method,
			&i.Corrected,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const submitRegister = `-- name: SubmitRegister :execrows
UPDATE attendance_registers
SET status = 'submitted', submitted_at = now(), submitted_by = $1
WHERE tenant_id = $2 AND id = $3 AND status = 'open'
`

type SubmitRegisterParams struct {
	SubmittedBy pgtype.UUID
	TenantID    pgtype.UUID
	ID          pgtype.UUID
}

func (q *Queries) SubmitRegister(ctx context.Context, arg SubmitRegisterParams) (int64, error) {
	result, err := q.db.Exec(ctx, submitRegister, arg.SubmittedBy, arg.TenantID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const totalsPerStudent = `-- name: TotalsPerStudent :many
WITH cur AS (
    SELECT DISTINCT ON (r.register_id, r.student_id) r.student_id, r.status
    FROM attendance_records r
    JOIN attendance_registers g ON g.tenant_id = r.tenant_id AND g.id = r.register_id
    WHERE r.tenant_id = $1 AND g.status = 'submitted'
      AND g.day BETWEEN $2::date AND $3::date
    ORDER BY r.register_id, r.student_id, r.version DESC
)
SELECT student_id,
       (count(*) FILTER (WHERE status = 'present'))::int AS present,
       (count(*) FILTER (WHERE status = 'late'))::int AS late,
       (count(*) FILTER (WHERE status = 'absent'))::int AS absent,
       (count(*) FILTER (WHERE status = 'leave'))::int AS leave
FROM cur
GROUP BY student_id
`

type TotalsPerStudentParams struct {
	TenantID pgtype.UUID
	FromDay  pgtype.Date
	ToDay    pgtype.Date
}

type TotalsPerStudentRow struct {
	StudentID pgtype.UUID
	Present   int32
	Late      int32
	Absent    int32
	Leave     int32
}

// Present, late, absent and leave days per student over submitted registers in a range.
func (q *Queries) TotalsPerStudent(ctx context.Context, arg TotalsPerStudentParams) ([]TotalsPerStudentRow, error) {
	rows, err := q.db.Query(ctx, totalsPerStudent, arg.TenantID, arg.FromDay, arg.ToDay)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TotalsPerStudentRow
	for rows.Next() {
		var i TotalsPerStudentRow
		if err := rows.Scan(
			&i.StudentID,
			&i.Present,
			&i.Late,
			&i.Absent,
			&i.Leave,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
